import{_ as p,a0 as s,w as d,s as a,I as e,x as i,a1 as l,A as o,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"5個有趣的Linux命令列技巧 | LCTT x X-CMD","titleTemplate":false,"description":"5個有趣的Linux命令列技巧 | LCTT (201505) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"5個有趣的Linux命令列技巧 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"5個有趣的Linux命令列技巧 | LCTT (201505) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201505/20150316 5 Interesting Command Line Tips and Tricks in Linux--Part 1","title":"5個有趣的Linux命令列技巧","tag":"201505","desc":""},"relativePath":"201505/20150316 5 Interesting Command Line Tips and Tricks in Linux--Part 1.md","filePath":"[post].md"}'),m={name:"201505/20150316 5 Interesting Command Line Tips and Tricks in Linux--Part 1.md"},u={id:"_1-我們可以使用history命令來查看曾經運行過的命令。",tabindex:"-1"};function f(T,t,x,w,h,g){const n=s("Link");return d(),a("div",null,[t[22]||(t[22]=e("h1",{id:"_5個有趣的linux命令列技巧",tabindex:"-1"},[i("5個有趣的Linux命令列技巧 "),e("a",{class:"header-anchor",href:"#_5個有趣的linux命令列技巧","aria-label":"Permalink to “5個有趣的Linux命令列技巧”"},"​")],-1)),t[23]||(t[23]=e("p",null,"你有將Linux物盡其用嗎？對很多Linux用户來説，有很多看起來是技巧的有用特性。有些時候你會需要這些技巧。本文會幫助你更好得使用一些命令，發揮其更強大的功能。",-1)),t[24]||(t[24]=e("p",null,[e("img",{src:"http://www.tecmint.com/wp-content/uploads/2015/03/5-Command-Line-Tips.jpg",alt:"5個命令列技巧"})],-1)),t[25]||(t[25]=e("p",null,[e("em",null,"圖1：5個命令列技巧")],-1)),t[26]||(t[26]=e("p",null,"我們開始一個新的系列，在這裏我們還會寫一些技巧，並且用盡量小的篇幅寫清楚。",-1)),e("h3",u,[t[1]||(t[1]=i("1. 我們可以使用",-1)),l(n,{href:"https://linux.cn/article-1143-1.html"},{default:o(()=>[...t[0]||(t[0]=[e("code",null,"history",-1),i("命令",-1)])]),_:1}),t[2]||(t[2]=i("來查看曾經運行過的命令。 ",-1)),t[3]||(t[3]=e("a",{class:"header-anchor",href:"#_1-我們可以使用history命令來查看曾經運行過的命令。","aria-label":"Permalink to “1. 我們可以使用history命令來查看曾經運行過的命令。”"},"​",-1))]),t[27]||(t[27]=r(`<p>這裏是一個<code>history</code>命令的示例輸出。</p><pre><code># history
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/history-command.gif" alt="history命令例子"></p><p><em>圖2：history命令例子</em></p><p>從<code>history</code>命令輸出看，很明顯，命令的執行時間沒有被打出來。有解決方法嗎？有的！運行如下命令：</p><pre><code># HISTTIMEFORMAT=&quot;%d/%m/%y %T &quot;
# history
</code></pre><p>如果你想讓這個修改永久生效，添加如下的一行內容到<code>~/.bashrc</code>文件中：</p><pre><code>export HISTTIMEFORMAT=&quot;%d/%m/%y %T &quot;
</code></pre><p>然後，在終端中運行：</p><pre><code># source ~/.bashrc
</code></pre><p>命令和選項的解釋：</p><ul><li>history – 查看運行過的命令</li><li>HISTIMEFORMAT – 設置時間格式的環境變量</li><li>%d – 天</li><li>%m – 月</li><li>%y – 年</li><li>%T – 時間戳</li><li>source – 簡而言之就是將文件內容發送給shell來執行</li><li>.bashrc – BASH以交互方式啓動時運行的腳本文件</li></ul><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/History-Command-Logs.gif" alt="history命令輸出的日誌"></p><p><em>圖3：<code>history</code>命令輸出的日誌</em></p><h3 id="_2-如何測試磁盤寫入速度" tabindex="-1">2. 如何測試磁盤寫入速度？### <a class="header-anchor" href="#_2-如何測試磁盤寫入速度" aria-label="Permalink to “2. 如何測試磁盤寫入速度？###”">​</a></h3><p>一行<code>dd</code>命令腳本就可以實現。</p><pre><code># dd if=/dev/zero of=/tmp/output.img bs=8k count=256k conv=fdatasync; rm -rf /tmp/output.img
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/dd-Command-Example.gif" alt="dd命令例子"></p><p><em>圖4：<code>dd</code>命令例子</em></p><p>命令和選項的解釋：</p><ul><li>dd – 轉換和複製文件</li><li>if=/dev/zero – 指定輸入文件，默認為stdin（標準輸入）</li><li>of=/tmp/output.img – 指定輸出文件，默認為stdout（標準輸出）</li><li>bs – 一次讀和寫的塊大小，最大可以以MB為單位</li><li>count – 複製次數</li><li>conv – 使用逗號分隔的策略來轉換文件（LCTT 譯註：比如將大寫字母轉換成小寫，echo AA | dd conv=lcase）</li><li>rm – 刪除文件和目錄</li><li>-rf – （-r） 遞歸地刪除目錄和其中的內容，（-f）強行刪除而不輸出確認信息</li></ul><h3 id="_3-你如何獲取吃掉你磁盤空間的最大的6個文件" tabindex="-1">3. 你如何獲取吃掉你磁盤空間的最大的6個文件？### <a class="header-anchor" href="#_3-你如何獲取吃掉你磁盤空間的最大的6個文件" aria-label="Permalink to “3. 你如何獲取吃掉你磁盤空間的最大的6個文件？###”">​</a></h3>`,22)),e("p",null,[t[5]||(t[5]=i("一個使用",-1)),l(n,{href:"http://www.tecmint.com/check-linux-disk-usage-of-files-and-directories/"},{default:o(()=>[...t[4]||(t[4]=[e("code",null,"du",-1),i("命令",-1)])]),_:1}),t[6]||(t[6]=i("的簡單單行腳本即可實現，",-1)),t[7]||(t[7]=e("code",null,"du",-1)),t[8]||(t[8]=i("命令主要用於獲取文件的空間使用情況。",-1))]),t[28]||(t[28]=r(`<pre><code># du -hsx * | sort -rh | head -6
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/check-disk-space-usage.gif" alt="獲取磁盤空間使用情況的方法"></p><p><em>圖5：獲取磁盤空間使用情況的方法</em></p><p>命令和選項的解釋：</p><ul><li>du – 估計文件的空間使用情況</li><li>-hsx – （-h）更易讀的格式，（-s）彙總輸出，（-x）跳過其他文件系統的文件</li><li>sort – 對文本文件按行排序</li><li>-rf – （-r）將比較的結果逆序輸出，（-f）忽略大小寫</li><li>head – 輸出文件的頭幾行</li></ul><h3 id="_4-獲取一個文件的詳細狀態信息" tabindex="-1">4. 獲取一個文件的詳細狀態信息### <a class="header-anchor" href="#_4-獲取一個文件的詳細狀態信息" aria-label="Permalink to “4. 獲取一個文件的詳細狀態信息###”">​</a></h3><p>可以使用<code>stat</code>命令</p><pre><code># stat filename_ext  （例如：stat abc.pdf）
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Check-File-Statistics.gif" alt="獲取文件的詳細信息"></p><p><em>圖6：獲取文件的詳細信息</em></p><h3 id="_5-顯示幫助" tabindex="-1">5. 顯示幫助 <a class="header-anchor" href="#_5-顯示幫助" aria-label="Permalink to “5. 顯示幫助”">​</a></h3><p>最後一個技巧是為那些入門者準備的，如果你是有經驗的用户，可能不需要它，除非你想從中尋找樂趣。入門者可能有Linux命令列恐懼症，下面的命令會隨機顯示一個man手冊頁。對入門者來説，好處是總會學到新的東西，而且不會厭倦。</p><pre><code># man $(ls /bin | shuf | head -1)
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Generate-Random-Man-Pages.gif" alt="查看隨機的man手冊頁"></p><p><em>圖7：查看隨機的man手冊頁</em></p><p>命令和選項的解釋：</p><ul><li>man – Linux man手冊</li><li>ls – 列出文件</li><li>/bin – 系統可執行文件的路徑</li><li>shuf – 把輸入內容按行隨機打亂並輸出</li><li>head – 輸出文件的頭幾行</li></ul><p>這就是所有的內容了。如果你知道任何類似的技巧，可以分享給我們，我們會用你的語言在網站上發表出來。</p><p>不要忘記在下邊評論框中留下有價值的反饋。保持聯繫。可以點贊或者將本文分享來幫助我們更好地傳播內容。</p><hr>`,20)),e("p",null,[t[10]||(t[10]=i("via: ",-1)),l(n,{href:"http://www.tecmint.com/5-linux-command-line-tricks/"},{default:o(()=>[...t[9]||(t[9]=[i("http://www.tecmint.com/5-linux-command-line-tricks/",-1)])]),_:1})]),e("p",null,[t[14]||(t[14]=i("作者：",-1)),l(n,{href:"http://www.tecmint.com/author/avishek/"},{default:o(()=>[...t[11]||(t[11]=[i("Avishek Kumar",-1)])]),_:1}),t[15]||(t[15]=i(" 譯者：",-1)),l(n,{href:"https://github.com/goreliu"},{default:o(()=>[...t[12]||(t[12]=[i("goreliu",-1)])]),_:1}),t[16]||(t[16]=i(" 校對：",-1)),l(n,{href:"https://github.com/wxy"},{default:o(()=>[...t[13]||(t[13]=[i("wxy",-1)])]),_:1})]),e("p",null,[t[19]||(t[19]=i("本文由 ",-1)),l(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[17]||(t[17]=[i("LCTT",-1)])]),_:1}),t[20]||(t[20]=i(" 原創翻譯，",-1)),l(n,{href:"http://linux.cn/"},{default:o(()=>[...t[18]||(t[18]=[i("Linux中國",-1)])]),_:1}),t[21]||(t[21]=i(" 榮譽推出",-1))])])}const k=p(m,[["render",f]]);export{C as __pageData,k as default};
